<?php
require dirname(__DIR__).'/config/bootstrap.php'; require_once dirname(__DIR__).'/includes/layout.php'; require_role('admin');
require_once dirname(__DIR__).'/includes/payroll.php';
$month=max(1,min(12,(int)($_POST['bulan']??$_GET['bulan']??date('n'))));$year=max(2020,min(2100,(int)($_POST['tahun']??$_GET['tahun']??date('Y'))));
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['mark_paid'])){
 require_csrf();$id=(int)($_POST['payroll_id']??0);$s=$pdo->prepare("UPDATE payroll SET status_bayar='dibayar',tanggal_bayar=CURDATE() WHERE id=? AND bulan=? AND tahun=? AND status_bayar='draft'");$s->execute([$id,$month,$year]);if($s->rowCount())audit_event($pdo,(int)current_user()['id'],'payroll.paid','payroll',$id,['bulan'=>$month,'tahun'=>$year]);flash($s->rowCount()?'success':'warning',$s->rowCount()?'Status payroll ditandai sudah dibayar.':'Payroll sudah dibayar atau tidak ditemukan pada periode ini.');redirect('/hris-presensi/admin/payroll.php?bulan='.$month.'&tahun='.$year);
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$start=sprintf('%04d-%02d-01',$year,$month);$periodStart=new DateTimeImmutable($start);$today=new DateTimeImmutable('today');$periodEnd=$periodStart->modify('last day of this month');if($periodStart>$today||($periodStart->format('Y-m')===$today->format('Y-m')&&$today<$periodEnd)){flash('danger','Payroll hanya dapat dihitung setelah periode bulan tersebut berakhir.');redirect('/hris-presensi/admin/payroll.php?bulan='.$month.'&tahun='.$year);}$end=$periodEnd->format('Y-m-d');$hs=$pdo->prepare('SELECT tanggal FROM hari_libur WHERE tanggal BETWEEN ? AND ?');$hs->execute([$start,$end]);$holidaySet=array_fill_keys($hs->fetchAll(PDO::FETCH_COLUMN),true);$done=0;$pdo->beginTransaction();
 try{
  $employeeQuery=$pdo->prepare("SELECT * FROM users WHERE role='karyawan' AND status_kerja='aktif' AND COALESCE(tanggal_masuk,DATE(created_at))<=?");$employeeQuery->execute([$end]);$employees=$employeeQuery->fetchAll();
  foreach($employees as $emp){
   $employmentStart=$emp['tanggal_masuk']?:substr($emp['created_at'],0,10);$effectiveStart=max($start,$employmentStart);$employeeWorkdays=weekdays_in_period($effectiveStart,$end,$holidaySet);$monthWorkdays=weekdays_in_period($start,$end,$holidaySet);
   $s=$pdo->prepare("SELECT SUM(status IN ('hadir','terlambat')) AS days_present,SUM(status IN ('izin','sakit','cuti')) AS days_leave,COALESCE(SUM(menit_terlambat),0) AS late_minutes FROM presensi WHERE user_id=? AND tanggal BETWEEN ? AND ?");$s->execute([$emp['id'],$effectiveStart,$end]);$att=$s->fetch();
   $o=$pdo->prepare("SELECT COALESCE(SUM(jam_lembur),0) FROM pengajuan WHERE user_id=? AND jenis='lembur' AND status='disetujui' AND tanggal_mulai BETWEEN ? AND ?");$o->execute([$emp['id'],$effectiveStart,$end]);$overtime=(float)$o->fetchColumn();
   $present=(int)$att['days_present'];$leave=(int)$att['days_leave'];$components=calculate_payroll_components($emp,$present,$leave,(int)$att['late_minutes'],$overtime,$employeeWorkdays,$monthWorkdays);
   $existing=$pdo->prepare('SELECT status_bayar FROM payroll WHERE user_id=? AND bulan=? AND tahun=?');$existing->execute([$emp['id'],$month,$year]);if($existing->fetchColumn()==='dibayar')continue;
   $up=$pdo->prepare("INSERT INTO payroll (user_id,bulan,tahun,gaji_pokok,tunjangan_makan,tunjangan_transport,uang_lembur,total_hadir,total_terlambat,total_lembur_jam,potongan_terlambat,potongan_alpha,potongan_bpjs,total_take_home_pay,status_bayar) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,'draft') ON DUPLICATE KEY UPDATE gaji_pokok=VALUES(gaji_pokok),tunjangan_makan=VALUES(tunjangan_makan),tunjangan_transport=VALUES(tunjangan_transport),uang_lembur=VALUES(uang_lembur),total_hadir=VALUES(total_hadir),total_terlambat=VALUES(total_terlambat),total_lembur_jam=VALUES(total_lembur_jam),potongan_terlambat=VALUES(potongan_terlambat),potongan_alpha=VALUES(potongan_alpha),potongan_bpjs=VALUES(potongan_bpjs),total_take_home_pay=VALUES(total_take_home_pay),status_bayar='draft',tanggal_bayar=NULL");
   $up->execute([$emp['id'],$month,$year,$components['base'],$components['meal'],$components['transport'],$components['overtime_pay'],$present,$components['late_hours'],$overtime,$components['late_deduction'],$components['alpha_deduction'],$components['bpjs_deduction'],$components['total']]);$done++;
  }
  $pdo->commit();audit_event($pdo,(int)current_user()['id'],'payroll.calculated','payroll',null,['bulan'=>$month,'tahun'=>$year,'jumlah_karyawan'=>$done]);flash('success',"Payroll {$month}/{$year} selesai dihitung untuk {$done} karyawan. Slip berstatus dibayar tidak diubah.");
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Payroll gagal dihitung. Periksa konfigurasi dan data kehadiran.');}
 redirect('/hris-presensi/admin/payroll.php?bulan='.$month.'&tahun='.$year);
}
$stmt=$pdo->prepare('SELECT p.*,u.nama,u.nip FROM payroll p JOIN users u ON u.id=p.user_id WHERE p.bulan=? AND p.tahun=? ORDER BY u.nama');$stmt->execute([$month,$year]);$rows=$stmt->fetchAll();page_header('Payroll'); ?>
<div class="mb-4"><div class="eyebrow">Penggajian</div><h1 class="page-title">Payroll bulanan</h1><p class="page-subtitle">Hitung gaji pokok, tunjangan hadir, lembur yang disetujui, keterlambatan, dan alpha.</p></div>
<div class="panel mb-4"><form method="post" class="d-flex flex-wrap align-items-end gap-2"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div><label class="form-label" for="payroll-month">Bulan</label><select class="form-select" id="payroll-month" name="bulan"><?php for($m=1;$m<=12;$m++): ?><option value="<?=$m?>" <?=$m===$month?'selected':''?>><?=e(date('F',mktime(0,0,0,$m,1)))?></option><?php endfor;?></select></div><div><label class="form-label" for="payroll-year">Tahun</label><input class="form-control" id="payroll-year" type="number" min="2020" max="2100" name="tahun" value="<?=$year?>"></div><button class="btn btn-primary">Hitung / perbarui draft</button><span class="small text-secondary">Hari libur yang tercatat di kalender admin tidak dihitung sebagai hari kerja.</span></form></div>
<section class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Karyawan</th><th>Hadir</th><th>Terlambat</th><th>Lembur</th><th>Potongan</th><th>Take-home pay</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td class="fw-semibold"><?=e($r['nama'])?><div class="small text-secondary"><?=e($r['nip'])?></div></td><td><?=(int)$r['total_hadir']?></td><td><?=(int)$r['total_terlambat']?></td><td><?=number_format((float)$r['total_lembur_jam'],1)?> jam</td><td><?=rupiah((float)$r['potongan_terlambat']+(float)$r['potongan_alpha'])?></td><td class="fw-bold"><?=rupiah($r['total_take_home_pay'])?></td><td><span class="badge text-bg-<?=$r['status_bayar']==='dibayar'?'success':'secondary'?>"><?=e(ucfirst($r['status_bayar']))?></span></td><td class="text-nowrap"><a class="btn btn-outline-secondary btn-sm" href="/hris-presensi/slip.php?id=<?=(int)$r['id']?>">Slip</a> <?php if($r['status_bayar']==='draft'): ?><form method="post" class="d-inline" onsubmit="return confirm('Tandai slip ini sebagai sudah dibayar?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="bulan" value="<?=$month?>"><input type="hidden" name="tahun" value="<?=$year?>"><input type="hidden" name="payroll_id" value="<?=(int)$r['id']?>"><button class="btn btn-success btn-sm" name="mark_paid" value="1">Bayar</button></form><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$rows): ?><tr><td colspan="8" class="text-center text-secondary py-4">Belum ada payroll. Pilih periode lalu tekan Hitung.</td></tr><?php endif;?></tbody></table></div></section>
<?php page_footer(); ?>
